import os; CHROME=os.environ.get("CHROME") or None  # set CHROME=/path/to/chrome to use system Chrome; default = Playwright Chromium
# pc-v31: workout mode rework (BRIEF-workout-mode.md). Two screen types: list mode for strength / supersets / carries
# (set rows + rest bar, no block timer) and full-screen clock mode for EMOM / intervals / flows / AMRAP.
import datetime as dt, re, json
from playwright.sync_api import sync_playwright
URL="http://localhost:8765/index.html";res=[];errs=[]
def ok(n,c,i=""): res.append(bool(c)); print(("PASS " if c else "FAIL ")+n+("" if c else " "+str(i)[:300]))
def ls(p,k): return p.evaluate("k=>{var v=localStorage.getItem(k);try{return JSON.parse(v)}catch(e){return v}}",k)
HOOK="""window.__bp=[];window.__vib=0;try{navigator.vibrate=function(){window.__vib++;return true;};}catch(e){}"""
def mk(b,d,seed=None,hour=8):
    y,m,dd=map(int,d.split("-"))
    c=b.new_context(viewport={"width":390,"height":844},device_scale_factor=2,is_mobile=True,has_touch=True,service_workers="block")
    c.add_init_script(HOOK);p=c.new_page();p.on("pageerror",lambda e:errs.append(str(e)));p.on("dialog",lambda x:x.accept())
    p.clock.install(time=dt.datetime(y,m,dd,hour,0));p.goto(URL)
    p.evaluate("t=>{localStorage.clear();localStorage.setItem('wo_startdate','\"2026-10-10\"');localStorage.setItem('wo_ver','12');for(var k in t)localStorage.setItem(k,JSON.stringify(t[k]));}",seed or {})
    p.reload();p.wait_for_timeout(150)
    if not p.locator("#panel.open").count(): p.click(f'button.day[data-d="{d}"]');p.wait_for_timeout(200)
    return c,p
def px(p,sel,prop="fontSize"): return float(p.locator(sel).evaluate(f"e=>parseFloat(getComputedStyle(e).{prop})"))
with sync_playwright() as pw:
    b=pw.chromium.launch(executable_path=CHROME,args=["--no-sandbox","--autoplay-policy=no-user-gesture-required"])
    # ---- EMOM data: Sat 24 single-bell EMOM 12 min = exactly 12 segments of 60 s, no READY / switch / timed rest
    c,p=mk(b,"2026-10-24")
    g=p.evaluate("()=>__how.SESS.kb24.blocks[1].segs")
    ok("EMOM 12 min → exactly 12 segments of 60 s",len(g)==12 and all(x[0]=="WORK" and x[1]==60 for x in g),[x[:2] for x in g])
    ok("EMOM labels: no switch / READY / round text",not [x for x in g if re.search(r"switch|READY|round \d",x[2])],[x[2] for x in g])
    ok("EMOM rotation: left, right, swings",[x[2] for x in g[:3]]==["Complex · left","Complex · right","Two-hand swing ×10"] and [x[2] for x in g[3:6]]==[x[2] for x in g[:3]])
    ok("EMOM header = 12:00",any(h.endswith("EMOM 60 s × 12 · 12:00") for h in p.locator("#sess h2").all_text_contents()),p.locator("#sess h2").all_text_contents())
    # ---- clock screen: NOW / clock / NEXT / minute counter, sizes, phase tint, start countdown
    p.click('[data-t="k24a"]');p.wait_for_timeout(60)
    ok("one 10 s get-ready at the start",p.locator("#ph").inner_text()=="GET READY" and p.locator("#time").inner_text()=="0:10" and p.locator("#sub").inner_text()=="Next: Complex · left")
    ok("clock is full screen",p.locator("#bar").evaluate("e=>{var r=e.getBoundingClientRect();return r.top<=1&&r.height>=840}"))
    p.clock.run_for(10500);p.wait_for_timeout(60)
    ok("top line: block name + Minute 1 of 12",p.locator("#ctop").inner_text()=="Single-bell EMOM · Minute 1 of 12",p.locator("#ctop").inner_text())
    ok("NOW = this minute's task",p.locator("#now").inner_text()=="Complex · left")
    ok("NEXT = next minute's task",p.locator("#sub").inner_text()=="Next: Complex · right")
    ok("clock counts the minute down",p.locator("#time").inner_text() in ("1:00","0:59"),p.locator("#time").inner_text())
    ok("sizes: clock ≥96 px > NOW 40–48 px > NEXT 16–18 px",px(p,"#time")>=96 and 40<=px(p,"#now")<=48 and 16<=px(p,"#sub")<=18 and px(p,"#time")>px(p,"#now")>px(p,"#sub"),(px(p,"#time"),px(p,"#now"),px(p,"#sub")))
    ok("controls have ≥44 px tap height",min(p.locator(f"#{x}").evaluate("e=>e.getBoundingClientRect().height") for x in ("tback","tpause","tnext","stop","tlock"))>=44)
    ok("work phase tints the screen orange",p.locator("#bar.p-work").count()==1)
    p.evaluate("()=>{window.__bp=[]}");p.clock.run_for(60000);p.wait_for_timeout(60)
    bp=p.evaluate("window.__bp")
    ok("minute change: 3-2-1 short beeps + 1 long",bp[:3]==[440,440,440] and bp[3]==988,bp)
    ok("Minute 2 of 12, NOW follows the rotation",p.locator("#ctop").inner_text().endswith("Minute 2 of 12") and p.locator("#now").inner_text()=="Complex · right" and p.locator("#sub").inner_text()=="Next: Two-hand swing ×10")
    # peek + lock
    p.click("#ctop");ok("tap block name peeks at the moves","Kettlebell clean" in p.locator("#peek").inner_text() and p.locator("#peek").is_visible());p.click("#ctop");ok("peek closes",not p.locator("#peek").is_visible())
    p.click("#tlock");ok("lock stops stray taps",p.locator("#bar.locked").count()==1 and p.locator("#tpause").evaluate("e=>getComputedStyle(e).pointerEvents")=="none")
    p.click("#tlock");ok("unlock",p.locator("#bar.locked").count()==0)
    p.evaluate("()=>{window.__bp=[]}");p.clock.run_for(11*60000+2000);p.wait_for_timeout(100)
    bp=p.evaluate("window.__bp");ok("block end: final double beep",bp[-2:]==[988,988],bp[-6:])
    ok("EMOM logged done",(ls(p,"wo_2026-10-24") or {}).get("s",{}).get("k24a")==1)
    ok("no vibration",p.evaluate("window.__vib")==0)
    c.close()
    # ---- intervals: work and rest both timed, round counter counts work only, rest phase is dark
    c,p=mk(b,"2026-10-20")
    p.click('[data-t="u20fl"]');p.clock.run_for(10500);p.wait_for_timeout(60)
    ok("intervals NOW: Row · 0:30 · moderate, Round 1 of 5",p.locator("#now").inner_text()=="Row · 0:30 · moderate" and p.locator("#cctr").inner_text()=="Round 1 of 5",p.locator("#bar").inner_text())
    p.clock.run_for(30000);p.wait_for_timeout(60)
    ok("rest phase: Rest · light paddle, still Round 1 of 5, dark",p.locator("#now").inner_text()=="Rest · light paddle" and p.locator("#cctr").inner_text()=="Round 1 of 5" and p.locator("#bar.p-rest").count()==1)
    p.clock.run_for(30000);p.wait_for_timeout(60);ok("Round 2 of 5",p.locator("#cctr").inner_text()=="Round 2 of 5")
    p.click("#stop")
    # flow: elapsed of total, one move per segment
    p.click('[data-t="u20wu"]');p.clock.run_for(15000);p.wait_for_timeout(60)
    ok("flow top line: elapsed of total",re.fullmatch(r"0:0[45] of 4:00",p.locator("#cctr").inner_text()),p.locator("#cctr").inner_text())
    p.click("#stop")
    # ---- list mode: strength rows, no block timer, tick → rest bar with the next set
    blk=p.locator(".blk").first
    ok("strength block has no guided timer",p.locator('#sess .blk [data-t]').count()==0 and p.locator('[data-t="u20a"],[data-t="u20b"],[data-t="u20c"]').count()==0)
    ok("straight sets: 4 rows of set | kg | reps | tick",blk.locator(".srow").count()==4 and blk.locator(".srow").first.locator("input.w").count()==1 and blk.locator(".srow").first.locator(".rpb").inner_text()=="6" and blk.locator(".srow").first.locator(".tk").count()==1)
    ok("rest shown on the card",blk.locator(".rs").inner_text()=="rest 1:45 after each set")
    blk.locator(".srow input.w").first.fill("18");blk.locator(".srow input.w").first.dispatch_event("change")
    ok("kg carries to the next sets",blk.locator(".srow input.w").nth(1).input_value()=="18")
    p.evaluate("()=>{window.__bp=[]}");blk.locator(".tk").first.click();p.wait_for_timeout(50)
    ok("tick a set → rest timer at the block's rest",p.locator("#rbar.show").count()==1 and p.locator("#rtime").inner_text()=="1:45")
    ok("rest bar: Next: set 2 · Dumbbell bench press 6 @ 18 kg",p.locator("#rlab").inner_text()=="Next: set 2 · Dumbbell bench press 6 @ 18 kg",p.locator("#rlab").inner_text())
    p.clock.run_for(106000);p.wait_for_timeout(60);bp=p.evaluate("window.__bp")
    ok("rest timer: 3-2-1 + one long beep at 0",bp==[440,440,440,1175],bp)
    p.click("#rskip")
    sup=p.locator(".blk").nth(1)
    ok("superset rows alternate B1, B2",[x.split("\n")[0] for x in sup.locator(".srow .sn").all_inner_texts()]==["1 · B1","1 · B2","2 · B1","2 · B2","3 · B1","3 · B2"])
    sup.locator(".tk").nth(0).click();ok("no rest between B1 and B2",p.locator("#rbar.show").count()==0)
    sup.locator(".tk").nth(1).click();ok("rest after the last move of the pair",p.locator("#rbar.show").count()==1 and p.locator("#rlab").inner_text().startswith("Next: set 2 · Assisted chin-up"),p.locator("#rlab").inner_text());p.click("#rskip")
    car=p.locator(".blk").nth(2)
    ok("carry row = distance, no countdown",car.locator('.srow[data-x="farmers-carry"] .rpb').first.inner_text()=="40 m" and car.locator("[data-t]").count()==0)
    car.locator(".tk").nth(0).click();car.locator(".tk").nth(1).click();ok("carry round tick → rest timer",p.locator("#rbar.show").count()==1);p.click("#rskip")
    p.click("#fin");p.clock.fast_forward(1000);p.wait_for_timeout(100);e=ls(p,"wo_log")[-1]
    ok("log keeps the old shape + optional per-set kg",e["wt"]["db-bench"]=="18" and e["rp"]["db-bench"]["v"]==[6,"–","–","–"] and e["rp"]["db-bench"]["k"]==["18","–","–","–"],e.get("rp"))
    c.close()
    # ---- AMRAP: one countdown, whole round as NOW, +1 round, score once at the end, then ticked
    c,p=mk(b,"2026-10-20")
    p.evaluate("""()=>{var S=__how.SESS.up20;S.blocks.splice(5,0,{k:"timer",id:"tamrap",h:"Flow",name:"AMRAP 6:00",note:"Each move: time shown · sides cued.",amrap:1,segs:[["WORK",360,"AMRAP"]],list:["Goblet squat × 8","Incline push-up × 8","Kettlebell swing × 10"],clk:1});}""")
    p.click("#close");p.click('button.day[data-d="2026-10-20"]');p.wait_for_timeout(150)
    p.click('[data-t="tamrap"]');p.clock.run_for(10500);p.wait_for_timeout(60)
    ok("AMRAP NOW shows the whole round",p.locator("#now").inner_text()=="Goblet squat × 8\nIncline push-up × 8\nKettlebell swing × 10",p.locator("#now").inner_text())
    ok("AMRAP has +1 round",p.locator("#tround").is_visible());p.click("#tround");p.click("#tround");p.click("#tround")
    p.clock.run_for(362000);p.wait_for_timeout(100)
    ok("score sheet at the end, rounds prefilled",p.locator("#scs.show").count()==1 and p.locator("#sc_r").input_value()=="3")
    p.fill("#sc_k","16");p.click('#sc_e [data-e="moderate"]');p.click("#sc_ok");p.wait_for_timeout(60)
    st=ls(p,"wo_2026-10-20");ok("score saved once and block ticked",st["sc"]["tamrap"]=={"r":3,"kg":"16","e":"moderate"} and st["s"]["tamrap"]==1,st.get("sc"))
    c.close()
    # ---- finished while locked → mark done prompt still works in clock mode
    c,p=mk(b,"2026-10-24");p.click('[data-t="k24a"]');p.clock.run_for(1000);p.clock.fast_forward(20*60*1000);p.wait_for_timeout(300)
    ok("locked phone: Mark done? prompt",p.locator("#bar.ask").count()==1 and "LOCKED" in p.locator("#ph").inner_text());p.click("#tqy")
    ok("Mark done ticks the block",(ls(p,"wo_2026-10-24") or {}).get("s",{}).get("k24a")==1);c.close()
    src=open("index.html",encoding="utf8").read()
    ok("no auto L/R split helper or segmented strength timer left",not re.search(r"function pushW|function bSup",src))
    ok("no navigator.vibrate",".vibrate(" not in src)
    ok("no page errors",not errs,errs[:3])
    b.close()
print(f"{sum(res)}/{len(res)} passed")
